/** Software root captures omit TextureView GPU contents. Composite at child
 * draw time so parent clips and later overlays retain their normal ordering. */
final class HalfSwordPreviewLayout extends LinearLayout {
 static int softwareTextureCaptures;
 HalfSwordPreviewLayout(Context context){super(context);}
 private boolean overlayGesture;
 private boolean controlAt(View v,int x,int y){if(v.getVisibility()!=VISIBLE)return false;Rect r=new Rect();if(!v.getGlobalVisibleRect(r)||!r.contains(x,y))return false;if(v instanceof Button||v instanceof SeekBar||v instanceof CompoundButton||v instanceof HalfSwordBodyPushPad||v instanceof HalfSwordAimPad)return true;if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=group.getChildCount()-1;i>=0;i--)if(controlAt(group.getChildAt(i),x,y))return true;}return false;}
 @Override public boolean dispatchTouchEvent(MotionEvent event){if(Boolean.TRUE.equals(getTag(0x7f0d74d4))){if(event.getActionMasked()==MotionEvent.ACTION_DOWN){overlayGesture=controlAt(this,(int)event.getRawX(),(int)event.getRawY());Object input=getParent() instanceof View?((View)getParent()).getTag(DogshitPlayer.CHAT_INPUT):null;if(input instanceof View&&((View)input).isShown()){int[] at=new int[2];((View)input).getLocationOnScreen(at);if(event.getRawY()>=at[1])overlayGesture=false;}}if(!overlayGesture)return false;}boolean handled=super.dispatchTouchEvent(event);if(event.getActionMasked()==MotionEvent.ACTION_UP||event.getActionMasked()==MotionEvent.ACTION_CANCEL)overlayGesture=false;return handled;}

 protected boolean drawChild(Canvas canvas,View child,long drawingTime){
  boolean result=super.drawChild(canvas,child,drawingTime);
  if(!canvas.isHardwareAccelerated()&&child instanceof HalfSwordView&&child.getVisibility()==VISIBLE&&child.getWidth()>0&&child.getHeight()>0){
   HalfSwordView texture=(HalfSwordView)child;
   if(texture.isAvailable()){
    Bitmap bitmap=texture.getBitmap();
    if(bitmap!=null){int saved=canvas.save();try{canvas.clipRect(child.getLeft(),child.getTop(),child.getRight(),child.getBottom());android.graphics.Paint composite=new android.graphics.Paint();composite.setAlpha(Math.round(child.getAlpha()*255));canvas.drawBitmap(bitmap,child.getLeft(),child.getTop(),composite);softwareTextureCaptures++;}finally{canvas.restoreToCount(saved);bitmap.recycle();}}
   }
  }
  return result;
 }
}

