  boolean result=super.drawChild(canvas,child,time);
  if(!canvas.isHardwareAccelerated()&&child instanceof HalfSwordView&&child.getVisibility()==VISIBLE&&child.getWidth()>0&&child.getHeight()>0){HalfSwordView texture=(HalfSwordView)child;if(texture.isAvailable()){Bitmap bitmap=texture.getBitmap();if(bitmap!=null){int saved=canvas.save();try{canvas.clipRect(child.getLeft(),child.getTop(),child.getRight(),child.getBottom());android.graphics.Paint composite=new android.graphics.Paint();composite.setAlpha(Math.round(child.getAlpha()*255));canvas.drawBitmap(bitmap,child.getLeft(),child.getTop(),composite);HalfSwordPreviewLayout.softwareTextureCaptures++;}finally{canvas.restoreToCount(saved);bitmap.recycle();}}}}
